import {initial,offers,machines,estimate,accept,start,inspect,rework,deliver,advance,action} from './engine.js';
const key='weldworks-save-v1';let s;try{s=JSON.parse(localStorage.getItem(key));if(!s||s.version!==1)throw 0;}catch{s=initial();offers(s);}let page='factory';let toastTimer;const $=x=>document.querySelector(x),yen=n=>'¥'+Math.round(n).toLocaleString('ja-JP'),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tabs=[['factory','▦','工場'],['orders','▤','受注市場'],['people','♙','従業員'],['equipment','⚙','設備・研究'],['finance','▥','財務']];const btn=(text,act,id='',cls='small',disabled=false)=>`<button class="${cls}" data-action="${act}" data-id="${id}" ${disabled?'disabled':''}>${text}</button>`;const metric=(name,value)=>`<div><span>${name}</span>${value}</div>`;const panel=(title,body,extra='')=>`<section class="panel"><div class="panelhead"><h2>${title}</h2>${extra}</div>${body}</section>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200)}
function save(){try{localStorage.setItem(key,JSON.stringify(s));}catch{toast('保存できません。ブラウザのストレージ設定を確認してください。')}}
function jobCard(j){return `<div class="job"><div class="row"><small>${esc(j.client)} · ${j.type}</small><span class="badge ${s.day>j.deadline?'red':'orange'}">${j.status}</span></div><h3>${j.name}</h3><div class="row"><small>納期まで ${j.deadline-s.day} 日</small><strong>${yen(j.reward)}</strong></div><div class="bar"><i style="width:${j.progress/j.work*100}%"></i></div><div class="row"><small>${Math.floor(j.progress/j.work*100)}% ${j.quality!=null?'· 品質 '+j.quality:''}</small><div class="actions">${j.status==='準備'?btn('配置・材料を準備 →','prepare',j.id):j.status==='検査待ち'?btn('品質検査','inspect',j.id):j.status==='納品待ち'?btn('納品する','deliver',j.id,'small primary')+(!j.reworked?btn('再加工','rework',j.id):''):'<small>翌営業日へ進めて生産</small>'}</div></div></div>`}
function factory(){let active=s.jobs.filter(j=>j.status==='生産中');let stations=s.equipment.map(m=>{let j=active.find(x=>x.machineId===m.id);return `<div class="station ${j&&!m.broken?'active':''}">${j?'<i class="person"></i>':''}<span class="machine-label">${machines[m.type].name} · ${m.broken?'要修理':j?'稼働中':'待機'}</span></div>`});for(let i=s.equipment.length;i<Math.min(8,s.level*2);i++)stations.push('<div class="station empty">＋<span class="machine-label">設備を設置できます</span></div>');return `<div class="grid"><div>${panel('第1工場',`<div class="factory"><span class="floor-label">WELD WORKS / PRODUCTION FLOOR</span><div class="stations">${stations.join('')}</div><div class="aisle"><span class="crates">▥ ▥ ▥</span><span>搬入・出荷エリア →</span></div></div><div class="factoryfoot"><span><i class="dot"></i>稼働 ${active.length} 台</span><span>設備 ${s.equipment.length} / ${s.level*2} 台</span><span>材料在庫 ${s.stock} 単位</span></div>`,`<span class="badge">Lv.${s.level} · ${s.level*120} m²</span>`)}${panel('生産スケジュール',s.jobs.length?s.jobs.map(jobCard).join(''):'<div class="emptytext">まだ受注している仕事はありません。<br>受注市場から最初の仕事を見つけましょう。</div>',btn('受注市場へ ↗','page','orders'))}</div><div>${panel('経営アドバイス',`<div class="panelbody"><span class="badge orange">MANAGEMENT NOTE</span><h3 style="margin-top:15px">${s.jobs.length?'利益を生む、確かな仕事を。':'はじめの一歩は、小さな受注から。'}</h3><p class="sub">鉄骨案件を受注し、佐藤さんと半自動溶接機を配置。品質を優先するなら「丁寧」を選びましょう。毎月30日の決算に備え、現金を残すことが大切です。</p><div class="metrics">${metric('月末の給与',yen(s.workers.reduce((n,w)=>n+w.salary,0)))}${metric('次の決算まで',(30-s.day%30)+' 日')}</div>${btn('経営ガイドを読む →','help')}</div>`)}${panel('会社の成長',`<div class="panelbody milestones"><div>会社の評判 <span>${Math.round(s.rep)} / 90</span></div><div class="bar"><i style="width:${s.rep}%"></i></div><div>累計確定利益 <span>${yen(s.totalProfit)} / 1,000万円</span></div><div>工場規模 <span>Lv.${s.level} / 3</span></div></div>`)}${panel('工場日誌',`<div class="panelbody">${s.logs.slice(0,4).map(l=>`<div class="feed"><time>DAY ${l.day}</time>${esc(l.text)}</div>`).join('')}</div>`)}</div></div>`}
function orders(){return `<div class="note">市場は7日ごとに更新。評判が高いほど報酬が増えます。満足度80以上で継続依頼が届き、長期契約は追加2回の発注を保証します。材料は配置時に購入・消費します。</div>${s.jobs.length?panel('進行中の受注',s.jobs.map(jobCard).join('')):''}<div class="cards">${s.offers.map(j=>`<article class="card"><div class="row"><span class="badge">${j.type}</span><span class="eyebrow">${j.contract?'長期契約':j.repeat?'継続取引':'新規案件'}</span></div><p>${j.client}</p><h3>${j.name}</h3><div class="value">${yen(j.reward)}</div><div class="metrics">${metric('納期',j.days+' 日')}${metric('要求品質',j.required+' / 100')}${metric('基準材料費',yen(j.material*6000))}${metric('必要評判 / 資格',j.minRep+' / '+(j.cert?'有資格':'なし'))}</div>${btn(s.rep<j.minRep?'評判 '+j.minRep+' で解放':'仕事を受注する →','accept',j.id,'primary',s.rep<j.minRep||s.bankrupt)}</article>`).join('')}</div>`}
function people(){return `<div class="note">従業員 ${s.workers.length} / ${s.level*4} 人。疲労は休業日・待機日に回復。技能に対して月給が低いと月末に意欲が低下し、意欲25未満で担当案件がなければ退職します。</div><div class="cards">${s.workers.map(w=>`<article class="card"><div class="row"><h2>${w.name}</h2><span class="badge">${w.training?'研修 残り'+w.training+'日':s.jobs.some(j=>j.workerId===w.id&&j.status==='生産中')?'稼働中':'待機中'}</span></div><p>${w.cert?'溶接資格 '+w.cert+'級':'資格未取得'} · 評価 ${w.skill>=75?'A':w.skill>=55?'B':'C'}</p><div class="metrics">${metric('技能',Math.round(w.skill))}${metric('月給',yen(w.salary))}${metric('意欲',w.morale+'%')}${metric('疲労',Math.round(w.fatigue)+'%')}</div><div class="bar"><i style="width:${w.skill}%"></i></div><div class="actions">${btn('技術研修 6万円','train',w.id)}${btn('資格取得 12万円','cert',w.id)}${btn('給与・昇給','salary',w.id)}${btn('賞与 5万円','bonus',w.id)}</div></article>`).join('')}</div><br>${panel('求人・面接',`<div class="panelbody">${s.candidates.length?s.candidates.map(w=>`<div class="job"><div class="row"><h3>${w.name}</h3><span class="badge">面接済み</span></div><p class="sub">技能 ${w.skill} / 資格 ${w.cert} / 希望月給 ${yen(w.salary)}<br>${w.cert?'精密な溶接と後進育成が得意な経験者。':'幅広い現場経験を積みたい成長志向の職人。'}</p><br>${btn('採用する','hire',w.id,'primary')}</div>`).join(''):`<p class="sub">求人広告で応募者を集め、面接情報を確認して採用します。</p><br>${btn('求人を掲載する · 3万円','recruit','','primary')}`}</div>`)}`}
function equipment(){return `<div class="cards">${s.equipment.map(m=>`<article class="card"><span class="badge ${m.broken?'red':''}">${m.broken?'故障・停止中':'使用可能'}</span><h3 style="margin-top:16px">${machines[m.type].name}</h3><div class="metrics">${metric('設備状態',Math.round(m.health)+'%')}${metric('稼働率',Math.round(m.busyDays/Math.max(1,s.day-1)*100)+'%')}${metric('生産能力',machines[m.type].capacity+' / 日')}${metric('月額保守費',yen(machines[m.type].maintenance))}</div><div class="bar"><i style="width:${m.health}%"></i></div>${btn(m.broken?'修理する · 8万円':'整備する · 2万円','maintain',m.id)}</article>`).join('')}</div><br>${panel('設備投資',`<div class="panelbody cards">${machines.map((m,i)=>`<article><h3>${m.name}</h3><p class="sub">対応：${m.types.join('・')}<br>能力 ${m.capacity}/日 · 品質 ${m.quality}<br>基礎故障率 ${(m.failure*100).toFixed(1)}%/稼働日<br>保守費 ${yen(m.maintenance)}/月</p><p><strong>${yen(m.price)}</strong></p>${btn('設備を購入','buy',i,'primary')}</article>`).join('')}</div>`)}<div class="cards"><div class="card"><h3>工場を増築</h3><p>設備枠＋2、人員枠＋4、受注枠＋1。作業環境の改善で品質も上昇します。月額賃料は3万円増加。</p>${btn('増築 · '+yen(s.level*1000000),'expand','','primary')}</div><div class="card"><h3>溶接技術の研究 Lv.${s.research}/10</h3><p>研究1レベルにつき、全案件の品質が2ポイント上昇します。</p>${btn('研究 · '+yen(200000*(s.research+1)),'research','','primary',s.research>=10)}</div><div class="card"><h3>鋼材の在庫</h3><p>保有 ${s.stock} 単位。先行購入した材料は案件の基準材料費から差し引かれます。</p>${btn('10単位購入 · 6万円','stock','','primary')}</div></div>`}
function finance(){let net=s.monthRevenue-s.monthExpense;return `<div class="note">売上と利益、現金は別ものです。融資は売上に含めず、元金返済は費用に含めません。設備・増築は購入時に全額費用処理するゲーム内の簡略会計です。現金がマイナスになると倒産します。</div><div class="grid"><div>${panel('今月の損益',`<div class="panelbody"><div class="metrics">${metric('売上',yen(s.monthRevenue))}${metric('費用',yen(s.monthExpense))}${metric('当月損益（決算前）',yen(net))}${metric('累計確定利益',yen(s.totalProfit))}</div><p class="sub">30日ごとに給与・賃料・保守費・利息・返済を支払い、黒字額にゲーム内税率20%を適用。</p></div>`)}${panel('月次決算履歴',s.history.length?`<div class="tablewrap"><table><thead><tr><th>決算日</th><th>売上</th><th>費用</th><th>税引後利益</th></tr></thead><tbody>${s.history.slice(-12).reverse().map(h=>`<tr><td>${h.day}日</td><td>${yen(h.revenue)}</td><td>${yen(h.expense)}</td><td class="${h.profit>=0?'positive':'negative'}">${yen(h.profit)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="emptytext">最初の決算は30日目です。</div>')}</div><div>${panel('銀行・資金繰り',`<div class="panelbody"><div class="metrics">${metric('借入残高',yen(s.debt))}${metric('年利（ゲーム設定）','4.5%')}${metric('融資限度額',yen(1000000+s.rep*20000))}${metric('月次元金返済',yen(Math.min(s.debt,50000)))}</div><div class="actions">${btn('50万円を借りる','loan','','primary')}${btn('50万円を返す','repay','', 'small',!s.debt)}</div><p class="sub" style="margin-top:18px">評判が上がると融資枠が増えます。返済原資を確保してから投資しましょう。</p></div>`)}</div></div>${panel('入出金明細',`<div class="tablewrap"><table><thead><tr><th>日付</th><th>摘要</th><th>金額</th></tr></thead><tbody>${s.ledger.slice(0,50).map(l=>`<tr><td>DAY ${l.day}</td><td>${l.category}</td><td class="${l.amount>=0?'positive':'negative'}">${l.amount>=0?'+':''}${yen(l.amount)}</td></tr>`).join('')}</tbody></table>${!s.ledger.length?'<div class="emptytext">取引はまだありません。</div>':''}</div>`)}`}
function render(){let title={factory:'工場ダッシュボード',orders:'受注市場',people:'従業員・人材育成',equipment:'設備・研究開発',finance:'財務・資金繰り'}[page];$('#app').innerHTML=`<aside><div class="brand"><span>W</span> 鋼の経営<small>WELD WORKS</small></div><div class="sidebar-title">MANAGEMENT</div><nav>${tabs.map(([p,i,t])=>`<button data-action="page" data-id="${p}" class="${page===p?'active':''}"><b>${i}</b>${t}</button>`).join('')}</nav><div class="sidefoot"><strong>町工場から、日本の頂点へ。</strong>会社ランク：${s.rep>=80?'全国企業':s.rep>=55?'地域の優良企業':'小さな町工場'}<div class="line"><i style="width:${s.rep}%"></i></div>経営目標達成まで、着実に。<br>${btn('ガイド・セーブ管理','help','','small')}</div></aside><main><header><div><div class="eyebrow">WELD WORKS MANAGEMENT</div><div class="company">坂田溶接工業 <span class="badge">${s.won?'日本代表企業':'創業 '+Math.ceil(s.day/30)+'か月目'}</span></div></div><div class="date"><div><small>営業日</small><strong>DAY ${String(s.day).padStart(3,'0')}</strong></div>${btn('翌営業日へ →','next','','gold',s.bankrupt)}</div></header><div class="pagehead"><div><h1>${title}</h1><p class="sub">ひとつの溶接から、会社の未来をつくる。</p></div><span class="badge">● 自動保存 / シングルプレイ</span></div>${s.bankrupt?'<div class="note danger"><strong>支払不能により倒産しました。</strong> 財務を振り返り、ガイドから新しい会社で再挑戦できます。 '+btn('新しく始める','reset')+'</div>':s.cash<650000?'<div class="note alert">運転資金に注意。月末の支払いに備え、納品または銀行融資で現金を確保しましょう。</div>':''}${s.won?'<div class="note">目標達成！日本を代表する溶接企業になりました。このまま自由経営を続けられます。</div>':''}<div class="stats"><div class="stat"><label>現預金</label><strong>${yen(s.cash)}</strong><small>借入残高 ${yen(s.debt)}</small></div><div class="stat"><label>今月の売上</label><strong>${yen(s.monthRevenue)}</strong><small>納品実績 ${s.delivered} 件</small></div><div class="stat"><label>今月の損益</label><strong class="${s.monthRevenue-s.monthExpense>=0?'positive':'negative'}">${yen(s.monthRevenue-s.monthExpense)}</strong><small>月末固定費・税引き前</small></div><div class="stat"><label>会社の評判</label><strong>${Math.round(s.rep)} <span style="font-size:13px;color:#9aa694">/ 100</span></strong><small>顧客満足度 ${Math.round(s.satisfaction)}%</small></div></div>${({factory,orders,people,equipment,finance}[page])()}<footer class="sub" style="margin-top:16px">WELD WORKS · 経営シミュレーション　${btn('遊び方・保存','help','','small')}</footer></main>`;save()}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}
function prepare(id){let j=s.jobs.find(x=>x.id===id);modal(`<h2>製造の準備</h2><p class="sub">${j.name} / 要求品質 ${j.required}</p><label class="field">担当従業員<select id="worker">${s.workers.map(w=>`<option value="${w.id}">${w.name} / 技能 ${Math.round(w.skill)}${w.training?'（研修中）':''}</option>`).join('')}</select></label><label class="field">使用設備<select id="machine">${s.equipment.map(m=>`<option value="${m.id}">${machines[m.type].name}${m.broken?'（故障中）':''}</option>`).join('')}</select></label><label class="field">材料等級<select id="grade"><option value="1">標準材</option><option value="2">高品質材 · ＋1,800円/単位</option><option value="3">最高品質材 · ＋3,600円/単位</option></select></label><label class="field">作業方針<select id="mode"><option>標準</option><option>丁寧</option><option>急行</option></select></label><div class="forecast" id="forecast"></div><div class="actions">${btn('材料を購入して生産開始','start',id,'primary')}${btn('キャンセル','close')}</div>`);let update=()=>{let g=Number($('#grade').value),e=estimate(s,j,$('#worker').value,$('#machine').value,g,$('#mode').value);$('#forecast').innerHTML=`予測品質 <strong>${e.quality}</strong> / 要求 ${j.required}<br>所要日数 約${e.speed?Math.ceil(j.work/e.speed):'—'}日 · 材料支出 ${yen((j.material-Math.min(s.stock,j.material))*6000+(g-1)*j.material*1800)}<br><small>疲労・設備摩耗で変動します。故障・遅延は含みません。</small>`};$('#modal').onchange=update;update()}
function help(){modal(`<h2>鋼の経営へようこそ</h2><ol class="help"><li>受注市場で、手持ちの設備に合う仕事を受注。</li><li>担当者・設備・材料・作業方針を選び、生産開始。</li><li>「翌営業日へ」で進行。完成後に品質検査・納品。</li><li>利益を残し、採用・資格・設備投資で事業を拡大。</li></ol><p class="sub">品質＝技能45%＋設備性能30%＋設備状態10%＋材料・資格・研究・環境・作業方針の加点−疲労。品質そのものに乱数はありません。故障のみ確率で発生します。</p><p class="sub">目標：評判90、累計確定利益1,000万円、工場Lv.3。現金がマイナスで倒産。ゲーム内の価格・税率・資格は簡略化した架空の設定です。</p><p class="sub">端末・ブラウザごとに自動保存。ブラウザのデータ削除で進行も消えます。バックアップを書き出して保管できます。</p><br><div class="actions">${btn('閉じる','close','','primary')}${btn('セーブを書き出す','export')}${btn('セーブを読み込む','import')}${btn('新しく始める','reset')}</div>`)}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=Number(b.dataset.id);try{if(a==='close'){$('#modal').close();return}if(a==='page'){page=b.dataset.id;render();window.scrollTo(0,0);return}if(a==='help'){help();return}if(a==='export'){let blob=new Blob([JSON.stringify(s)],{type:'application/json'}),u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='weldworks-day-'+s.day+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return}if(a==='import'){let input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{let v=JSON.parse(await input.files[0].text());validateSave(v);s=v;$('#modal').close();render();toast('セーブを読み込みました。')}catch{toast('有効なセーブファイルではありません。')}};input.click();return}if(a==='reset'){modal(`<h2>新しい会社で始めますか？</h2><p>現在の進行を上書きします。必要なら先にセーブを書き出してください。</p><div class="actions">${btn('新しい会社で始める','confirm-reset','','primary')}${btn('キャンセル','close')}</div>`);return}if(a==='confirm-reset'){s=initial();offers(s);page='factory';$('#modal').close();render();return}if(s.bankrupt)throw Error('倒産した会社では操作できません。');if(a==='prepare'){prepare(id);return}if(a==='salary'){let w=s.workers.find(x=>x.id===id);modal(`<h2>${w.name}の給与設定</h2><p class="sub">昇給で意欲が上昇します。目安月給 ${yen(180000+w.skill*800)}</p><label class="field">月給（円）<input id="salary" type="number" min="180000" max="1000000" step="10000" value="${w.salary}"></label>${btn('給与を設定','setSalary',id,'primary')} ${btn('キャンセル','close')}`);return}if(a==='setSalary'){action(s,'salary',id,Number($('#salary').value));$('#modal').close()}else if(a==='next')advance(s);else if(a==='accept')accept(s,id);else if(a==='start'){start(s,id,Number($('#worker').value),Number($('#machine').value),Number($('#grade').value),$('#mode').value);$('#modal').close()}else if(a==='inspect')inspect(s,id);else if(a==='deliver')deliver(s,id);else if(a==='rework')rework(s,id);else action(s,a,id);render();if(a!=='next')toast('更新しました。')}catch(err){toast(err.message)}});
function validateSave(v){if(!v||v.version!==1||!Number.isFinite(v.cash)||!Number.isInteger(v.day)||v.day<1)throw Error();for(let k of ['workers','equipment','jobs','offers','candidates','ledger','history','logs'])if(!Array.isArray(v[k]))throw Error();for(let k of ['debt','rep','satisfaction','level','research','monthRevenue','monthExpense','totalProfit','delivered','stock','nextId'])if(!Number.isFinite(v[k]))throw Error();for(let w of [...v.workers,...v.candidates]){if(typeof w.name!=='string'||/[<>&"']/.test(w.name)||!Number.isFinite(w.skill)||!Number.isFinite(w.salary))throw Error();}for(let m of v.equipment)if(!machines[m.type])throw Error();for(let j of [...v.jobs,...v.offers]){for(let k of ['name','client','type'])if(typeof j[k]!=='string'||/[<>&"']/.test(j[k]))throw Error();}for(let l of v.ledger)if(typeof l.category!=='string'||/[<>&"']/.test(l.category))throw Error();}
try{validateSave(s)}catch{s=initial();offers(s)}render();
